#!/usr/bin/env python3
"""Reproduce edition-7 section and clinical entry profiles from reviewed catalog."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
CATALOG=json.loads((ROOT/'spec/edition7-content.json').read_text())
NAMES={22:'AmbAllergyIntolerance',33:'AmbMedicationAdministration',34:'AmbMedicationStatement',38:'AmbCondition',39:'AmbCarePlan',40:'AmbProcedure',41:'AmbLinkedDocument'}
def profile_name(entry): return NAMES.get(entry['number'],f"AmbEntry{entry['number']}")
def main():
    f=['// Generated by scripts/generate_content_profiles.py from spec/edition7-content.json.']
    for e in CATALOG['entries']:
        if e['resource']!='Observation':continue
        n=e['number']
        f += ['',f'Profile: AmbEntry{n}','Parent: AmbObservation',f'Id: semd-amb-entry-{n}',f'Title: "{e["title"]}"',f'Description: "{e["requirement"]}, раздел {e["section"]} редакции 7. MustSupport относится к получателю; кратности и инварианты задают наличие данных."']
        f += ['* ^status = #draft']
        if e['code']:
            f += [f'* code = urn:oid:1.2.643.5.1.13.13.99.2.166#{e["code"]}']
        for d in e['direct']:
            if not d['required']:continue
            field={'effectiveTime':'effective[x]','performer':'performer','text':'note','value':'value[x]'}[d['field']]
            if field=='value[x]':
                key=f'amb-entry-{n}-value'
                f += [f'* obeys {key}']
            else:f += [f'* {field} 1..{"*" if field in ("performer","note") else "1"} MS']
        if n in (24,25,26,27,28,29,30,31,32):f += ['* performer.extension[sourceRole] 1..1 MS']
        if n in (27,28,29,30,31,32):f += ['* obeys amb-period-pair']
        if n in (30,31):f += ['* effective[x] only Period','* effectivePeriod.start 1..1 MS','* effectivePeriod.end 1..1 MS']
        if n==37:f += ['* obeys amb-score-content','* hasMember only Reference(AmbQualifier8019)','* derivedFrom only Reference(AmbQualifier8020)']
        qs=[q for q in e.get('qualifiers',[]) if n!=37]
        if qs:
            minimum=sum(int(q['cardinality'].split('..')[0]) for q in qs)
            if minimum:f += [f'* hasMember {minimum}..* MS']
            targets=' or '.join('AmbQualifier'+q['code'] for q in qs)
            f += [f'* hasMember only Reference({targets})']
            clauses=[]
            for q in qs:
                count=f"hasMember.resolve().ofType(Observation).where(code.coding.where(system = 'urn:oid:1.2.643.5.1.13.13.99.2.166' and code = '{q['code']}').exists()).count()"
                low,high=q['cardinality'].split('..')
                if int(low):clauses.append(f'{count} >= {low}')
                if high!='*':clauses.append(f'{count} <= {high}')
            if clauses:
                f += [f'* obeys amb-entry-{n}-details']
                expr='hasMember.all(resolve().exists()) implies ('+' and '.join(clauses)+')'
                f += ['',f'Invariant: amb-entry-{n}-details',f'Description: "Обязательные и повторяющиеся уточнения {e["requirement"]}; проверяется при доступных целях ссылок, в частности в документном Bundle."','Severity: #error',f'Expression: "{expr}"']
        for d in e['direct']:
            if d['field']!='value' or not d['required']:continue
            nullable=d['allow_absent'];expr='value.exists() or dataAbsentReason.exists()' if nullable else 'value.exists()'
            f += ['',f'Invariant: amb-entry-{n}-value',f'Description: "{d["requirement"]}: значение'+(' или явная причина его отсутствия.' if nullable else ' обязательно.')+'"','Severity: #error',f'Expression: "{expr}"']
    for q in CATALOG['qualifiers']:
        f += ['',f'Profile: AmbQualifier{q["code"]}','Parent: AmbObservation',f'Id: semd-amb-qualifier-{q["code"]}',f'Title: "{q["title"]}"',f'Description: "Уточняющая запись {q["code"]}, разделы {", ".join(q["sections"])}. Основания: {", ".join(q["requirements"][:3])}."','* ^status = #draft',f'* code = urn:oid:1.2.643.5.1.13.13.99.2.166#{q["code"]}']
        for field in q.get('required_fields',[]):
            f += ['* effective[x] 1..1 MS' if field=='effectiveTime' else '* note 1..* MS']
        if q['code']=='8004':f += ['* obeys amb-gestational-unit']
        if q['value_required']:
            expr='value.exists() or dataAbsentReason.exists()' if q['allow_absent'] else 'value.exists()'
            f += [f'* obeys amb-qualifier-{q["code"]}-value','',f'Invariant: amb-qualifier-{q["code"]}-value','Description: "Значение уточняющей записи обязательно согласно требованиям её вида."','Severity: #error',f'Expression: "{expr}"']
    f += ['','RuleSet: AmbSections', '* section ^slicing.discriminator.type = #pattern','* section ^slicing.discriminator.path = "code"','* section ^slicing.rules = #open']
    for s in CATALOG['sections']:
        name=s['code'].lower();card='1..1' if s['required'] else '0..1'
        es=[e for e in CATALOG['entries'] if e['section']==s['code']]
        names=[profile_name(e) for e in es]
        if s['code'] in ('DGN','LINKDOCS'):names.append('AmbObservation')
        if s['code']=='IMM':names.append('AmbImmunization')
        minimum=sum(int(e['cardinality'].split('..')[0]) for e in es)
        if s['code']=='IMM':minimum=1
        f += [f'* section contains {name} {card} MS',f'* section[{name}] ^short = "{s["title"]}"',f'* section[{name}] ^comment = "{s["requirement"]}; таблица 6, страницы 58–59. Наличие необязательной секции не делает её содержимое необязательным."',f'* section[{name}].code 1..1 MS',f'* section[{name}].code = $SectionTypes#{s["code"]}',f'* section[{name}].entry {minimum}..* MS',*[f'* section[{name}].entry ^type[0].targetProfile[{i}] = Canonical({target})' for i,target in enumerate(names)]]
        if s['code']=='ALL':f += [f'* section[{name}].entry 1..* MS']
        clauses=[]
        for e in es:
            if s['code']=='IMM':continue
            low,high=e['cardinality'].split('..')
            count=f"entry.resolve().ofType({e['resource']})"
            if e['code'] and e['resource']=='Observation':
                count+=f".where(code.coding.where(system = 'urn:oid:1.2.643.5.1.13.13.99.2.166' and code = '{e['code']}').exists())"
            count+='.count()'
            if int(low):clauses.append(f'{count} >= {low}')
            if high!='*':clauses.append(f'{count} <= {high}')
        if clauses:f += [f'* section[{name}] obeys amb-section-{name}-entries']
    for s in CATALOG['sections']:
        if s['code']=='IMM':continue
        clauses=[]
        for e in (e for e in CATALOG['entries'] if e['section']==s['code']):
            low,high=e['cardinality'].split('..')
            count=f"entry.resolve().ofType({e['resource']})"
            if e['code'] and e['resource']=='Observation':count+=f".where(code.coding.where(system = 'urn:oid:1.2.643.5.1.13.13.99.2.166' and code = '{e['code']}').exists())"
            count+='.count()'
            if int(low):clauses.append(f'{count} >= {low}')
            if high!='*':clauses.append(f'{count} <= {high}')
        if clauses:
            expr='entry.all(resolve().exists()) implies ('+' and '.join(clauses)+')'
            f += ['',f'Invariant: amb-section-{s["code"].lower()}-entries',f'Description: "Обязательность и повторяемость записей раздела {s["code"]}; проверяется при доступных целях ссылок, в частности внутри документного Bundle."','Severity: #error',f'Expression: "{expr}"']
    (ROOT/'input/fsh/Amb_Content.fsh').write_text('\n'.join(f)+'\n')

    page=['### Каталог данных редакции 7','', 'Каталог задаёт область поддержки получателя по [правилу MustSupport](support.html). Основание: руководство СЭМД 290 редакции 7, таблица 6 и требования У1–У3. Перечень разделов взят из руководства, а не из комплектного примера.','', '### Разделы документа','', '| Код | Содержание | Наличие секции |','|---|---|---|']
    for section in CATALOG['sections']:
        page.append(f'| {section["code"]} | {section["title"]} | {"1..1" if section["required"] else "0..1"} |')
    page += ['', '### Клинические записи','', 'Кратность ниже действует **внутри присутствующей секции**. Условные правила дополняют её. В IMM допустима вакцинация вместо применения невакцинного препарата; в ALL обязательно хотя бы текстовое или структурированное описание.','', '| Требование | Раздел | Профиль | Кратность |','|---|---|---|---|']
    ids={22:'allergy-intolerance',33:'medication-administration',34:'medication-statement',38:'condition',39:'care-plan',40:'procedure',41:'linked-document'}
    for e in CATALOG['entries']:
        pid='semd-amb-'+ids[e['number']] if e['number'] in ids else 'semd-amb-entry-'+str(e['number'])
        page.append(f'| {e["requirement"]} | {e["section"]} | [{e["title"]}](StructureDefinition-{pid}.html) | {e["cardinality"]} |')
    page += ['', '### Уточняющие сведения','', 'Связанные Observation сохраняют исходное кодирование уточнения, значение, дату, примечание и собственные уточнения через hasMember. Входы шкалы 8020 связываются через derivedFrom, интерпретация 8019 — через hasMember. Уточнения диагноза и реквизитов документа имеют focus на соответствующий Condition/DocumentReference и включаются в секцию вместе с ним. Обязательность значения уточнения задаёт его профиль.','', '| Код | Сведения | Разделы |','|---|---|---|']
    for q in CATALOG['qualifiers']:
        page.append(f'| {q["code"]} | [{q["title"]}](StructureDefinition-semd-amb-qualifier-{q["code"]}.html) | {", ".join(q["sections"])} |')
    page += ['', '### Контекст и общие поля','', '| Данные руководства | Представление и поддерживаемые поля |','|---|---|',
    '| У1-4–У1-11: документ | Bundle.identifier; Composition.identifier, version, type, title, date, language, meta.security |',
    '| У1-12: пациент | Patient.identifier (МИС, СНИЛС, удостоверяющий документ, полис), type, value, assigner, period; name.family/given (отчество — следующее given); gender, birthDate, address, telecom, managingOrganization |',
    '| Представительство | RelatedPerson.patient, identifier, relationship, name, address, telecom; Patient.contact.organization для представителя-организации; тип документа о полномочиях — Identifier.type |',
    '| У1-13–У1-15: участники | Composition.author, custodian; PractitionerRole.identifier, code, practitioner, organization, contact; Practitioner.identifier, name, address, telecom; получатели — вложенный раздел контекста Composition.section с ролью recipient и ссылкой на Organization |',
    '| Организация и подразделение | Organization.identifier (ФРМО, лицензия, ОГРН/ОГРНИП, ОКПО, ОКАТО), name, partOf, contact.address, contact.telecom; подразделение — отдельная Organization |',
    '| Адрес | text, postalCode, use; расширения RuCore address-type, regionRF, fias с aoguid и houseguid; исходная точность сохраняется |',
    '| У1-17: оплата | Coverage.type, identifier.type/value/assigner, period.start/end, insurer, paymentBy.party; идентификатор организации-плательщика сохраняет ИНН и другие переданные реквизиты |',
    '| Направление | ServiceRequest.identifier, authoredOn, requester; PractitionerRole и Organization направившей стороны; ссылка в разделе контекста Composition; реквизиты направления могут передаваться DocumentReference без вымышленного заказа |',
    '| Документируемое событие | Procedure.code, occurrence, performer.function/actor, recorder; Composition.event.detail; статус не выводится из отсутствующих сведений |',
    '| У1-21: случай помощи | Encounter.identifier, subject, serviceProvider, class, priority, serviceType, actualPeriod.start/end, partOf.identifier.type/value, diagnosis.condition/use |',
    '| Лекарственная терапия | MedicationStatement.effectivePeriod либо расширение длительности; dosage.timing.repeat, route, doseAndRate.doseQuantity, patientInstruction; Medication.code, doseForm, ingredient и расширение торгового наименования |',
    '| Результаты вмешательств, трансфузия, изделия | Observation с кодом вмешательства/компонента крови/наименованием изделия, датой/периодом, результатом, исполнителями и уточнениями. Это сообщённые сведения источника, не новое назначение или самостоятельно подтверждённое событие |',
    '| Анестезиологическое пособие | Связанная Observation с исходным видом пособия и текстом; NA при неприменении и OTH при некодируемом виде не подменяются фактом введения лекарства |',
    '| Числовые, интервальные и кодированные значения | valueQuantity/Range, comparator и границы, valueCodeableConcept, valueString, valueBoolean; referenceRange.low/high/text; Coding.system/code/display/version; оригинальная единица НСИ — расширение semd-amb-source-unit |',
    '| Внутренние ссылки | Reference на ресурс в Bundle; derivedFrom для результата и документа, hasMember для уточнений, focus для характеристики диагноза/документа; дополнительный тип связи — semd-amb-clinical-link-type |',
    '| Связанные документы | DocumentReference.type, identifier, description, content.attachment.creation; серия/номер/форма — связанные Observation либо типизированный Identifier, без обязательного наличия файла |',
    '', 'В профилях открытые срезы и расширения сохраняют допустимые дополнительные сведения. Неизвестный клинический вариант нельзя молча свести к ближайшему коду или заменить только narrative. Поддержка всех допустимых типов отмеченного value[x] обязательна для получателя; выбор типа определяется содержанием и справочником параметра.',
    '', '### Условные требования', '',
    '| Условие | Требование к передаваемым данным | Проверка |','|---|---|---|',
    '| Телемедицинская консультация (У3-2) | DOCINFO содержит место проведения, код 8 НСИ 1.2.643.5.1.13.13.11.1008 | Контекстная проверка: признак телемедицины не выводится из отсутствия места |',
    '| Нет текстового аллергоанамнеза (У3-22) | В ALL есть хотя бы одна структурированная аллергологическая запись | Минимум одна ссылка ALL; типы ссылок ограничены профилями |',
    '| OTH для кодируемого понятия | Сохраняется текстовое пояснение, если оно предписано руководством: выявленная патология, аллерген, подкомиссия, отдельные лабораторные тесты, вмешательство, анестезия, изделие | Инвариант общего Observation для code/value с OTH; специальные требования текста остаются контекстными |',
    '| Причина инвалидности 19, проявление реакции 15, цель комиссии/консилиума 10 | Обязательно соответствующее текстовое уточнение | Проверка кодированного значения вместе с текстом/примечанием |',
    '| Бессрочная инвалидность | Для верхней границы сохраняется PINF | Проверка исходного смысла; отсутствие end само по себе не означает бессрочность |',
    '| Результаты исследований с периодом | Передаются начало и конец согласно руководству; точечная дата не превращается в период | Проверка формы effective[x] и границ |',
    '| Шкала: нет результата и интерпретации | Обязателен хотя бы один параметр; иначе обязателен результат либо интерпретация (У3-37) | value или hasMember/derivedFrom; профили связанных записей различают их смысл |',
    '| Продолжительность терапии | Пара дат либо длительность; две формы взаимоисключающие (У3-34.1.4) | Инвариант периода/длительности; пара границ периода |',
    '| Доза СМНН / не СМНН | Для СМНН нет единицы и есть пояснение потребительской единицы; для другого препарата единица обязательна | Инвариант дозы и правило conventions.html |',
    '| Неизвестен код препарата | Обязательна лекарственная форма; вещество обязательно при отсутствии торгового наименования; назначение по торговому наименованию требует его сохранения | Контекстная проверка Medication и ссылки на него |',
    '| Схема приёма | Однократное применение допускает NA; иначе сохраняются интервал и точность, без подмены периодичности длительностью | Timing.repeat и timing-exact; неизвестные значения явно обозначаются |',
    '| Вид оплаты и тип полиса | ОМС/ДМС/договор, серия, номер, ИНН, срок действия и причины NA/NAV/NASK должны согласовываться с видом оплаты (У1-17) | Контекстная проверка Coverage, Identifier и организации |',
    '| Передано подразделение организации | Сохраняются идентификатор и наименование подразделения (У1-12) | Organization.partOf и отдельная Organization |',
    '', 'Условия, зависящие от факта вне документа (например, назначение по торговому наименованию), проверяются отправителем по исходным данным. Валидатор экземпляра не доказывает выполнение таких условий. Сведения, отсутствующие в источнике, не создают ради прохождения проверки.']
    (ROOT/'input/pagecontent/content.md').write_text('\n'.join(page)+'\n')

if __name__=='__main__':main()
